const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state={region:'US',saved:'16011',area:'16011',source:'default',permitted:false,shop:'',service:'Oil change full synthetic',page:'map',selected:null};
const services=['Oil change full synthetic','Tire rotation','Wheel alignment'];
const records=[{id:1,name:'Firestone Complete',address:'1100 W Stearns Rd',distance:'1.4',price:58.67,rating:'4.7 (256)',logo:true,x:68,y:54},{id:2,name:'Pep Boys',address:'1250 E Main St',distance:'2.1',price:62.49,rating:'4.6 (184)',x:12,y:72},{id:3,name:'Valvoline Instant Oil Change',address:'800 W Main St',distance:'2.8',price:64.99,rating:'4.8 (210)',x:78,y:18}];
function areaLabel(){return state.source==='device'?'Current location':state.area||'Not selected'}
function postcode(){return state.region==='CA'?'postal code':'ZIP code'}
function valid(v){return state.region==='CA'?/^[ABCEGHJ-NPRSTVXY]\d[ABCEGHJ-NPRSTVWXYZ] ?\d[ABCEGHJ-NPRSTVWXYZ]\d$/i.test(v):/^\d{5}$/.test(v)}
function normalize(v){v=v.trim().toUpperCase();return state.region==='CA'?v.replace(/\s/g,'').replace(/^(.{3})(.{3})$/,'$1 $2'):v}
function notify(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',3500)}
function filtered(){return records.filter(r=>r.name.toLowerCase().replace(/\s/g,'').includes(state.shop.toLowerCase().replace(/\s/g,'')))}
function sync(){ $('#activeRead').textContent=areaLabel();$('#savedRead').textContent=state.saved||'None';$('#shopRead').textContent=state.shop||'All shops'; }
function title(text,back='map'){return `<div class="title"><button aria-label="Back" data-page="${back}"><span class="icon back-icon" aria-hidden="true"></span></button>${text}</div>`}
function openSearch(){state.page='search';render();requestAnimationFrame(()=>$('#locationInput')?.focus())}
function render(){sync(); if(state.page==='map')renderMap();else if(state.page==='search')renderSearch();else renderDefault();$('#app').scrollTop=0;document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{state.page=b.dataset.page;render()})}
function logo(r){return r.logo?'<span class="logo firestone-icon" role="img" aria-label="Firestone"></span>':`<span class="logo" aria-hidden="true" style="font-size:22px;color:#db502d;font-weight:700">${r.name[0]}</span>`}
function renderMap(){const list=filtered();$('#app').innerHTML=`<header class="head">${title('Find routine maintenance fast','map')}<button id="areaButton" class="searchbar" aria-label="Change search location"><span class="icon search-icon" aria-hidden="true"></span><span>${state.area?'Near '+esc(areaLabel()):'Choose a location'}</span></button><label class="sr" for="service">Service</label><select class="service" id="service">${services.map(s=>`<option ${s===state.service?'selected':''}>${s}</option>`).join('')}</select><div class="locationline"><span>${state.saved?'Default location: '+esc(state.saved):'No default location saved'}</span><button id="editDefault">${state.saved?'Edit':'Add'}</button></div></header><div class="map" aria-label="Design reference map with sample shop markers"><img src="assets/map.png" alt="Map from the Flutter design">${state.source==='device'?'<span class="dot" aria-label="Simulated device location"></span>':''}${state.area?list.map(r=>`<button class="marker ${state.selected===r.id?'selected':''}" style="left:${r.x}%;top:${r.y}%" data-marker="${r.id}" aria-label="Show ${r.name}">${r.logo?'<span class="firestone-icon pin-logo" aria-hidden="true"></span>':r.name[0]}</button>`).join(''):''}<span class="mapbadge">${state.area?esc(areaLabel())+' · Sample map':'Choose an area to see shops'}</span></div><section class="drawer"><div class="handle"></div><div class="vehicle"><span>2021 Toyota Camry</span></div><div class="drawerfilters"><span class="distance">Distance</span><button class="shopfilter" id="shopButton" aria-expanded="false" aria-controls="shopFilterForm">By shop${state.shop?': '+esc(state.shop):''} <span aria-hidden="true">⌄</span></button>${state.shop?'<button class="clearfilter" id="clearShop" aria-label="Clear shop filter">×</button>':''}</div><form id="shopFilterForm" class="shopfilterform" hidden><label for="drawerShopInput">Shop name</label><div class="field"><span class="icon search-icon" aria-hidden="true"></span><input id="drawerShopInput" placeholder="Search shop name" value="${esc(state.shop)}"></div><div class="filteractions"><button class="text" type="button" id="cancelShop">Cancel</button><button class="primary" type="submit">Apply</button></div></form>${!state.area?`<div class="empty"><h2>Find shops near you</h2><p>Enter your ${postcode()} or use your current location.</p><button class="primary" id="choose">Choose location</button></div>`:list.length?list.map(r=>`<article id="shop-${r.id}" class="shop ${state.selected===r.id?'selected':''}"><div class="shopmain">${logo(r)}<div class="shopinfo"><div class="shopname">${r.name}</div><div class="sub">${r.address} · <span class="orange">${r.distance} ${state.region==='CA'?'km':'mi'}</span></div><div class="rating"><span class="star-icon" aria-hidden="true"></span>${r.rating}</div></div>${state.region==='US'?`<div class="price">$${(r.price+(state.service==='Wheel alignment'?25:state.service==='Tire rotation'?-30:0)).toFixed(2)}</div>`:''}</div><button class="primary book" data-book="${r.id}">${state.region==='CA'?'Find a walk-in':'Schedule Service'}</button></article>`).join(''):`<div class="empty"><h2>No matching shops</h2><p>No sample shops match “${esc(state.shop)}” near ${esc(areaLabel())}.</p><button class="primary" id="clearEmpty">Show all shops</button><button class="text" id="changeEmpty">Change location</button></div>`}</section><dialog class="modal" id="booking"><h2>Continue with this shop</h2><p id="bookingText"></p><p>Booking is outside this location prototype. No request has been created.</p><button class="primary" id="closeBooking">Back to shops</button></dialog>`;
 $('#areaButton').onclick=()=>openSearch('location');$('#shopButton').onclick=()=>{const form=$('#shopFilterForm');form.hidden=!form.hidden;$('#shopButton').setAttribute('aria-expanded',String(!form.hidden));if(!form.hidden)$('#drawerShopInput').focus()};$('#cancelShop').onclick=()=>{$('#shopFilterForm').hidden=true;$('#drawerShopInput').value=state.shop;$('#shopButton').setAttribute('aria-expanded','false');$('#shopButton').focus()};$('#shopFilterForm').onsubmit=e=>{e.preventDefault();state.shop=$('#drawerShopInput').value.trim();state.selected=null;render();$('#shopButton').focus()};$('#editDefault').onclick=()=>{state.returnPage='map';state.page='default';render();$('#defaultInput').focus()};$('#service').onchange=e=>{state.service=e.target.value;render()};$('#choose')?.addEventListener('click',()=>openSearch());const clear=()=>{state.shop='';state.selected=null;render();notify('Shop filter cleared. Search area unchanged.')};$('#clearShop')?.addEventListener('click',clear);$('#clearEmpty')?.addEventListener('click',clear);$('#changeEmpty')?.addEventListener('click',()=>openSearch());document.querySelectorAll('[data-marker]').forEach(b=>b.onclick=()=>{state.selected=Number(b.dataset.marker);render();$('#shop-'+state.selected)?.scrollIntoView({block:'nearest',behavior:'smooth'})});document.querySelectorAll('[data-book]').forEach(b=>b.onclick=()=>{const r=records.find(r=>r.id===Number(b.dataset.book));$('#bookingText').textContent=`${r.name} · ${state.service} · ${areaLabel()} · 2021 Toyota Camry`;$('#booking').showModal();});$('#closeBooking').onclick=()=>$('#booking').close();
}
function renderSearch(){let draftDevice=state.source==='device';$('#app').innerHTML=`<header class="head">${title('Search location')}</header><form class="formbody" id="searchForm"><label for="locationInput">Location</label><div class="field"><span class="icon search-icon" aria-hidden="true"></span><input id="locationInput" autocomplete="postal-code" placeholder="Enter ${postcode()}" value="${esc(state.area?areaLabel():'')}" ${draftDevice?'readonly':''}></div><button type="button" class="text" id="useDevice">Use your current location</button>${draftDevice?'<button type="button" class="text" id="manual" style="display:block">Enter '+postcode()+'</button>':''}<p class="hint" id="firstSave">${!state.saved?'Your first '+postcode()+' will be saved as your default.':''}</p><label class="check" id="saveOption" style="${!state.saved||draftDevice?'display:none!important':''}"><input type="checkbox" id="saveSearch">Save this as my default location</label><p class="error" id="error" role="alert"></p><button class="primary sectiongap" type="submit">Search</button><button class="cancel" type="button" id="cancelSearch">Cancel</button><div class="savedbox">Default: ${esc(state.saved||'Not set')}<button type="button" class="text" id="defaultFromSearch">${state.saved?'Edit':'Add'}</button></div></form>`;
 const input=$('#locationInput');const error=$('#error');input.addEventListener('input',()=>{draftDevice=false;error.textContent=''});$('#manual')?.addEventListener('click',()=>{draftDevice=false;input.readOnly=false;input.value='';input.focus();$('#manual').hidden=true;$('#saveOption').style.display=state.saved?'flex':'none';});$('#useDevice').onclick=()=>{const outcome=$('#permission').value;if(outcome!=='allow'){error.textContent=outcome==='deny'?'Location permission is denied. Enter a '+postcode()+' to continue.':'We couldn’t get your location. Enter a '+postcode()+' or try again.';return}state.permitted=true;draftDevice=true;input.value='Current location';input.readOnly=true;$('#saveOption').style.setProperty('display','none','important');if(!$('#manual')){const b=document.createElement('button');b.type='button';b.className='text';b.textContent='Enter '+postcode();b.style.display='block';b.onclick=()=>{draftDevice=false;input.readOnly=false;input.value='';input.focus();b.remove();$('#saveOption').style.display=state.saved?'flex':'none'};$('#useDevice').after(b)}error.textContent='';notify('Using simulated device location')};
 $('#cancelSearch').onclick=()=>{state.page='map';render()};$('#defaultFromSearch').onclick=()=>{state.returnPage='search';state.page='default';render();$('#defaultInput').focus()};$('#searchForm').onsubmit=e=>{e.preventDefault();const value=normalize(input.value);if(!draftDevice&&!valid(value)){error.textContent='Enter a valid '+(state.region==='CA'?'Canadian postal code, such as M5V 2T6.':'5-digit ZIP code.');input.focus();return}state.area=draftDevice?'Current location':value;state.source=draftDevice?'device':'manual';if(!draftDevice&&(!state.saved||$('#saveSearch').checked)){state.saved=value;notify('Default location saved')}state.selected=null;state.page='map';render()};
}
function renderDefault(){const back=state.returnPage||'map';$('#app').innerHTML=`<header class="head">${title('Default location',back)}</header><form class="formbody" id="defaultForm"><p class="hint">Used when your current location is unavailable. Also saved in Personal Information.</p><div class="searcharea">Currently searching near<strong>${esc(areaLabel())}</strong></div><label for="defaultInput">${state.region==='CA'?'Postal code':'ZIP code'}</label><div class="field"><span class="icon search-icon" aria-hidden="true"></span><input id="defaultInput" autocomplete="postal-code" placeholder="${state.region==='CA'?'M5V 2T6':'30328'}" value="${esc(state.saved||'')}"></div><label class="check sectiongap"><input type="checkbox" id="alsoSearch">Also use this area for my current search</label><p class="error" id="defaultError" role="alert"></p><button class="primary sectiongap" type="submit">Save default</button><button class="cancel" type="button" id="cancelDefault">Cancel</button></form>`;$('#cancelDefault').onclick=()=>{state.page=back;render()};$('#defaultForm').onsubmit=e=>{e.preventDefault();const value=normalize($('#defaultInput').value);if(!valid(value)){$('#defaultError').textContent='Enter a valid '+postcode()+'.';return}state.saved=value;const use=$('#alsoSearch').checked;if(use){state.area=value;state.source='manual'}state.page=back;render();notify(use?'Default and search area updated.':'Default saved. Search area unchanged.')};}
function reset(){state.region=$('#region').value;const s=$('#scenario').value;state.saved=['zip','both'].includes(s)?(state.region==='CA'?'M5V 2T6':'16011'):null;state.permitted=['device','both'].includes(s);state.shop='';state.service=services[0];state.selected=null;fresh()}
function fresh(){state.area=state.permitted?'Current location':state.saved;state.source=state.permitted?'device':state.saved?'default':null;state.shop='';state.page='map';render()}
$('#scenario').onchange=reset;$('#region').onchange=reset;$('#reset').onclick=reset;$('#fresh').onclick=fresh;render();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_location_prototype',description:'Read the current simulated search area, saved default and shop filter.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({area:areaLabel(),savedDefault:state.saved,shopFilter:state.shop,region:state.region,page:state.page})})).catch(()=>{})}catch{}}
